// Validation BEFORE any SSH. Rejects malformed input, control characters and legacy slugs.
const raw = $('Webhook').first().json.body;
const b = (raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : {};
const cfg = $('Config').first().json;
const run_id = 'run-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
const errors = [];
const CTRL = /[\u0000-\u001f\u007f]/;
const LEGACY = ['jjbags-in', 'jj-bags-com', 'jjbags', 'jj-bags', 'jjbags.in', 'jj-bags.com', 'sa', 'qubix', 'qubix-sa'];
const isStr = (v) => typeof v === 'string';
const slug = isStr(b.slug) ? b.slug : '';
if (!/^[a-z][a-z0-9-]{1,20}$/.test(slug)) errors.push('slug must match ^[a-z][a-z0-9-]{1,20}$');
if (LEGACY.includes(slug)) errors.push('slug is reserved (legacy site)');
for (const f of ['clientName', 'businessName']) {
const v = b[f];
if (!isStr(v) || v.trim().length === 0) errors.push(f + ' is required');
else if (v.length > 80) errors.push(f + ' must be <= 80 chars');
else if (CTRL.test(v)) errors.push(f + ' must not contain control characters');
}
const email = isStr(b.adminEmail) ? b.adminEmail : '';
if (email.length > 254 || !/^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/.test(email)) errors.push('adminEmail is not a valid email');
let brandColor = '';
if (b.brandColor !== undefined && b.brandColor !== null && b.brandColor !== '') {
if (!isStr(b.brandColor) || !/^#[0-9a-fA-F]{6}$/.test(b.brandColor)) errors.push('brandColor must match ^#[0-9a-fA-F]{6}$');
else brandColor = b.brandColor;
}
let extra = 0;
if (b.debug_extra_reserve_mib !== undefined && b.debug_extra_reserve_mib !== null) {
const d = b.debug_extra_reserve_mib;
if (typeof d !== 'number' || !Number.isFinite(d) || d < 0) errors.push('debug_extra_reserve_mib must be a number >= 0');
else extra = d;
}
const ok = errors.length === 0;
const safeSlug = (isStr(b.slug) ? b.slug : '').replace(/[^\x20-\x7e]/g, '?').slice(0, 40);
const now = new Date().toISOString();
return [{ json: {
ok, run_id, cfg, errors,
input: ok ? { slug, clientName: b.clientName, businessName: b.businessName, adminEmail: email, brandColor, debug_extra_reserve_mib: extra } : null,
resp_code: 422,
resp: { status: 'invalid', run_id, errors },
rec: { run_id, slug: safeSlug, attempt_no: 0, phase: 'preflight', started_at: now, finished_at: now, exit_code: null, classification: 'invalid', decision: 'invalid_input', capacity_json: '', output_tail: '', note: errors.join('; ').slice(0, 500) },
} }];

const v = $('Validate').first().json;
const row = $input.first().json || {};
let exists = false, why = '';
if (row.slug === v.input.slug) {
const t = Date.parse(row.updated_at || row.updatedAt || '');
if (row.status === 'provisioning' && Number.isFinite(t) && (Date.now() - t) < 2 * 3600 * 1000) { exists = true; why = 'provisioning in progress'; }
else if (row.status === 'active') { exists = true; why = 'client already active'; }
}
const now = new Date().toISOString();
return [{ json: {
exists, resp_code: 409,
resp: { status: 'conflict', reason: why, run_id: v.run_id },
rec: { run_id: v.run_id, slug: v.input.slug, attempt_no: 0, phase: 'preflight', started_at: now, finished_at: now, exit_code: null, classification: 'conflict', decision: 'slug_exists_in_registry', capacity_json: '', output_tail: '', note: why },
} }];

const v = $('Validate').first().json;
const cmd = "echo '##MEM'; free -m | awk '/^Mem:/{print $7}'; echo '##NPROC'; nproc; echo '##LOAD'; cat /proc/loadavg; " +
"echo '##DISK'; p=/var/lib/docker; [ -d \"$p\" ] || p=/; df -Pm \"$p\" | awk 'NR==2{print $4}'; " +
"echo '##PROJECTS'; docker compose ls -a -q; echo \"##DOCKER_RC=$?\"; echo '##END'";
return [{ json: { ...v, preflight_cmd: cmd, preflight_started_at: new Date().toISOString() } }];

// Pre-flight evaluation. FAIL CLOSED: anything failed/unparseable => blocked_preflight_failed.
// "available" from `free -m` already reflects both legacy stacks (Elasticsearch included) and the OS,
// which is exactly Task 2.4's requirement that the formula subtracts the two legacy stacks.
const v = $('Validate').first().json;
const cfg = v.cfg;
const started = $('Prep Preflight').first().json.preflight_started_at;
const r = $input.first().json || {};
const finished = new Date().toISOString();
const extra = v.input.debug_extra_reserve_mib || 0;
const reserve = Number(cfg.reserve_mib) + extra;
let decision = 'blocked_preflight_failed', reasons = [], cap = {}, projects = [], owned = false;
const sshOk = r.error === undefined && r.code === 0 && typeof r.stdout === 'string';
if (!sshOk) {
reasons.push('pre-flight SSH failed: ' + String((r.error && (r.error.message || r.error)) || 'no successful result (connection failure or missing exit status)').slice(0, 200));
} else {
const sec = {};
let cur = null;
for (const line of r.stdout.split('\n')) {
    const m = line.trim().match(/^##([A-Z_]+)(?:=(.*))?$/);
    if (m) { cur = m[1]; sec[cur] = m[2] !== undefined ? [m[2]] : []; }
    else if (cur && line.trim() !== '') sec[cur].push(line.trim());
}
const avail = Number((sec.MEM || [])[0]);
const nproc = Number((sec.NPROC || [])[0]);
const lp = ((sec.LOAD || [])[0] || '').split(/\s+/).map(Number);
const disk = Number((sec.DISK || [])[0]);
const rc = (sec.DOCKER_RC || [])[0];
const parsed = [avail, nproc, disk, lp[0], lp[1], lp[2]].every((n) => Number.isFinite(n)) && nproc > 0 && rc === '0' && sec.END !== undefined;
if (!parsed) {
    reasons.push('pre-flight output unparseable or docker listing failed');
} else {
    projects = sec.PROJECTS || [];
    const perClient = Number(cfg.per_client_mib);
    const load5pc = lp[1] / nproc;
    const fit = Math.max(0, Math.floor((avail - reserve) / perClient));
    const ramOk = (avail - reserve) >= perClient;
    const cpuOk = load5pc <= Number(cfg.max_load_per_core);
    const diskOk = disk >= Number(cfg.min_free_disk_mib);
    cap = { available_mib: avail, nproc, load1: lp[0], load5: lp[1], load15: lp[2], load5_per_core: Math.round(load5pc * 1000) / 1000,
        free_disk_mib: disk, per_client_mib: perClient, reserve_mib: Number(cfg.reserve_mib), debug_extra_reserve_mib: extra, reserve_effective_mib: reserve,
        max_load_per_core: Number(cfg.max_load_per_core), min_free_disk_mib: Number(cfg.min_free_disk_mib),
        clients_that_fit: fit, checks: { ram: ramOk, cpu: cpuOk, disk: diskOk }, project_count: projects.length };
    if (projects.includes('qubix-' + v.input.slug)) { decision = 'slug_taken'; reasons.push('project qubix-' + v.input.slug + ' already exists'); }
    else if (!ramOk || !cpuOk || !diskOk) {
        decision = 'blocked_capacity';
        if (!ramOk) reasons.push('RAM: available ' + avail + ' - reserve ' + reserve + ' < per-client ' + perClient);
        if (!cpuOk) reasons.push('CPU: load5/core ' + cap.load5_per_core + ' > ' + cfg.max_load_per_core);
        if (!diskOk) reasons.push('disk: free ' + disk + ' MiB < ' + cfg.min_free_disk_mib);
    } else { decision = 'proceed'; owned = true; } // project proven ABSENT => this run owns whatever it creates
}
}
const proceed = decision === 'proceed';
const recDecision = { proceed: 'proceed', slug_taken: 'slug_taken', blocked_capacity: 'blocked — insufficient capacity', blocked_preflight_failed: 'blocked_preflight_failed' }[decision];
const resp_code = { proceed: 202, slug_taken: 409, blocked_capacity: 503, blocked_preflight_failed: 503 }[decision];
const now = new Date().toISOString();
const state = {
...v, decision, proceed, owned_by_run: owned, capacity: cap, reasons, attempt_no: 0, history: [],
resp_code,
resp: proceed ? { status: 'accepted', run_id: v.run_id, slug: v.input.slug, capacity: { available_mib: cap.available_mib, clients_that_fit: cap.clients_that_fit } }
    : { status: decision, run_id: v.run_id, reasons, capacity: cap.available_mib === undefined ? null : { available_mib: cap.available_mib, clients_that_fit: cap.clients_that_fit, checks: cap.checks } },
rec: { run_id: v.run_id, slug: v.input.slug, attempt_no: 0, phase: 'preflight', started_at: started, finished_at: finished, exit_code: sshOk ? 0 : (typeof r.code === 'number' ? r.code : null),
    classification: proceed ? 'ok' : (decision === 'slug_taken' ? 'terminal' : 'blocked'), decision: recDecision, capacity_json: JSON.stringify(cap), output_tail: '', note: reasons.join('; ').slice(0, 500) },
client: { slug: v.input.slug, client_name: v.input.clientName, business_name: v.input.businessName, subdomain: v.input.slug + '.' + cfg.domain,
    site_url: 'https://' + v.input.slug + '.' + cfg.domain, admin_url: 'https://' + v.input.slug + '.' + cfg.domain + '/admin', status: 'provisioning',
    last_run_id: v.run_id, est_ram_mib: Number(cfg.per_client_mib), legacy: false, read_only: false, updated_at: now },
alert_to: cfg.alert_email,
alert_subject: '[Qubix fleet] Onboarding BLOCKED for ' + v.input.slug + ': ' + recDecision,
alert_text: 'Onboarding of "' + v.input.slug + '" was stopped BEFORE any deployment action.\nDecision: ' + recDecision + '\nReasons: ' + reasons.join('; ') + '\nCapacity: ' + JSON.stringify(cap) + '\nRun: ' + v.run_id,
};
return [{ json: state }];

const st = $input.first().json;
const cfg = st.cfg, inp = st.input;
const attempt_no = (st.attempt_no || 0) + 1;
// Hard bound: the loop can never exceed max_attempts.
if (attempt_no > Number(cfg.max_attempts)) throw new Error('attempt bound exceeded');
if (st.proceed !== true) throw new Error('deploy reached without a proceed decision');
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'"; // the ONLY way user values enter a shell command
let args = ' --slug=' + q(inp.slug) + ' --client-name=' + q(inp.clientName) + ' --business-name=' + q(inp.businessName) + ' --admin-email=' + q(inp.adminEmail);
if (inp.brandColor) args += ' --brand-color=' + q(inp.brandColor);
const dir = cfg.base_dir + '/qubix-' + inp.slug;
const cmd = 'd=' + q(dir) + '; [ -d "$d/.git" ] || git clone --branch fleet --depth 1 ' + q(cfg.repo_url) + ' "$d" || exit 10; cd "$d" && scripts/provision-client.sh' + args;
return [{ json: { ...st, attempt_no, deploy_cmd: cmd, attempt_started_at: new Date().toISOString() } }];

// Ruling (Task 4.3): 0 success, 1-9 terminal, 10-19 transient,
// ANY other value (125/127/255, null, signal) or an SSH node error/timeout => DEFAULT-TO-TRANSIENT.
const st = $('Prep Deploy').item.json;
const r = $input.first().json || {};
const cfg = st.cfg;
const errored = r.error !== undefined;
const code = (!errored && typeof r.code === 'number') ? r.code : null;
let cls;
if (code === 0) cls = 'success';
else if (code !== null && code >= 1 && code <= 9) cls = 'terminal';
else cls = 'transient';
const out = errored ? '' : String(r.stdout || '');
const err = errored ? String((r.error && (r.error.message || r.error)) || 'ssh error') : String(r.stderr || '');
let password = '';
const m = out.match(/Admin password \(generated, shown once\): (\S+)/);
if (m) password = m[1];
const redact = (s) => { let t = s.replace(/(Admin password \(generated, shown once\): )\S+/g, '$1[REDACTED]'); if (password) t = t.split(password).join('[REDACTED]'); return t; };
const tail = redact(out + (err ? '\n--stderr--\n' + err : '')).slice(-4000);
const now = new Date().toISOString();
const history = [...(st.history || []), { attempt_no: st.attempt_no, exit_code: code, classification: cls, tail }];
let next, mode = null, status = null, note;
if (cls === 'success') { next = 'success'; status = 'active'; note = 'provisioned'; }
else if (cls === 'terminal') { next = 'stop'; status = 'failed_terminal'; note = 'terminal exit ' + code + ': not retried, no teardown'; }
else if (!st.owned_by_run) { next = 'stop'; status = 'failed_escalated'; note = 'transient failure but project not proven owned by this run: no teardown'; }
else { next = 'teardown'; mode = st.attempt_no < Number(cfg.max_attempts) ? 'retry' : 'final'; note = 'transient (' + (errored ? 'ssh error' : 'exit ' + code) + '), attempt ' + st.attempt_no + '/' + cfg.max_attempts + ', ' + mode; }
const client = { ...st.client, status: status || 'provisioning', updated_at: now };
const allTails = history.map((h) => 'attempt ' + h.attempt_no + ' exit=' + h.exit_code + ' ' + h.classification + ':\n' + h.tail).join('\n\n');
const s2 = { ...st, history, last_class: cls, last_code: code, next, teardown_mode: mode, client,
secret_password: password,
rec: { run_id: st.run_id, slug: st.input.slug, attempt_no: st.attempt_no, phase: 'deploy', started_at: st.attempt_started_at, finished_at: now, exit_code: code, classification: cls, decision: 'deploy_attempt', capacity_json: '', output_tail: tail, note },
alert_to: cfg.alert_email,
alert_subject: '[Qubix fleet] Onboarding ' + (status || 'failed') + ' for ' + st.input.slug,
alert_text: 'Onboarding of "' + st.input.slug + '" stopped with status ' + status + '.\n' + note + '\nRun: ' + st.run_id + '\n\nOutput (redacted) of every attempt:\n' + allTails };
delete s2.deploy_cmd;
return [{ json: s2 }];

// The ONLY place the generated admin password is ever emitted.
const st = $('Classify').item.json;
const c = st.client;
return [{ json: { alert_to: st.cfg.alert_email, alert_subject: '[Qubix fleet] Client provisioned: ' + st.input.slug,
alert_text: 'Client "' + st.input.clientName + '" (' + st.input.slug + ') was provisioned.\nSite: ' + c.site_url + '\nAdmin: ' + c.admin_url + '\nAdmin email: ' + st.input.adminEmail + '\nAdmin password (shown once): ' + st.secret_password + '\nRun: ' + st.run_id } }];

const st = $input.first().json;
if (st.owned_by_run !== true || st.next !== 'teardown') throw new Error('teardown forbidden: not owned by this run');
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const slug = st.input.slug, base = st.cfg.base_dir;
const proj = q('qubix-' + slug);
const cmd = 'cd ' + q(base + '/qubix-' + slug) + ' && docker compose -f ' + q('docker-compose.' + slug + '.yml') + ' -p ' + proj + ' down -v --remove-orphans; docker compose ls -a -q | grep -qx ' + proj + ' && echo STILL_PRESENT || echo GONE';
return [{ json: { ...st, teardown_cmd: cmd, teardown_started_at: new Date().toISOString() } }];

const st = $('Prep Teardown').item.json;
const r = $input.first().json || {};
const cfg = st.cfg;
const errored = r.error !== undefined;
const out = errored ? '' : String(r.stdout || '');
const gone = !errored && r.code === 0 && /(^|\n)GONE\s*$/.test(out) && !/STILL_PRESENT/.test(out);
const tail = (errored ? String((r.error && (r.error.message || r.error)) || 'ssh error') : out + String(r.stderr || '')).slice(-4000);
const now = new Date().toISOString();
let status = null, cont = false, note;
if (!gone) { status = 'failed_teardown'; note = 'teardown did not prove project gone; retrying would hit the slug-collision check (exit 2), stopping'; }
else if (st.teardown_mode === 'retry') { cont = true; note = 'teardown ok, retrying after backoff'; }
else { status = 'failed_escalated'; note = 'attempts exhausted, teardown ok'; }
const client = { ...st.client, status: status || 'provisioning', updated_at: now };
const allTails = (st.history || []).map((h) => 'attempt ' + h.attempt_no + ' exit=' + h.exit_code + ' ' + h.classification + ':\n' + h.tail).join('\n\n');
return [{ json: { ...st, teardown_ok: gone, continue_retry: cont, client,
rec: { run_id: st.run_id, slug: st.input.slug, attempt_no: st.attempt_no, phase: 'teardown', started_at: st.teardown_started_at, finished_at: now, exit_code: errored ? null : (typeof r.code === 'number' ? r.code : null), classification: gone ? 'ok' : 'failed', decision: 'teardown', capacity_json: '', output_tail: tail, note },
alert_to: cfg.alert_email,
alert_subject: '[Qubix fleet] Onboarding ' + status + ' for ' + st.input.slug,
alert_text: 'Onboarding of "' + st.input.slug + '" ended with status ' + status + '.\n' + note + '\nRun: ' + st.run_id + '\n\nOutput (redacted) of every attempt:\n' + allTails + '\n\nTeardown output:\n' + tail } }];
